package io.knowledgebrain.space;
import org.springframework.context.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.core.annotation.Order;import org.springframework.http.HttpMethod;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.web.SecurityFilterChain;
@Configuration(proxyBeanMethods=false) @ConditionalOnProperty(name="brain.space.integration-authorization.enabled",havingValue="true")
class IntegrationAuthorizationSecurity {@Bean @Order(0) SecurityFilterChain integrationAuthorizationFilter(HttpSecurity http)throws Exception{return http.securityMatcher("/internal/space/integration-authorization").sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).requestCache(c->c.disable()).csrf(c->c.disable()).authorizeHttpRequests(a->a.requestMatchers(HttpMethod.POST,"/internal/space/integration-authorization").permitAll().anyRequest().denyAll()).build();}}
